WITH reason_agg AS ( SELECT cp.cp_catalog_page_id AS cp_id, cp.cp_department, r.r_reason_desc, cd.cd_gender, COUNT(*) AS return_events, SUM(cr.cr_return_amount) AS total_return_amount, AVG(cr.cr_return_quantity) AS avg_quantity, MAX(cr.cr_return_amount) AS max_return FROM catalog_returns cr JOIN catalog_page cp ON cr.cr_catalog_page_sk = cp.cp_catalog_page_sk JOIN reason r ON cr.cr_reason_sk = r.r_reason_sk JOIN customer_demographics cd ON cr.cr_returning_cdemo_sk = cd.cd_demo_sk WHERE cr.cr_return_tax IS NOT NULL GROUP BY cp.cp_catalog_page_id, cp.cp_department, r.r_reason_desc, cd.cd_gender ), ranked_reason AS ( SELECT cp_id, cp_department, r_reason_desc, cd_gender, return_events, total_return_amount, avg_quantity, max_return, RANK() OVER (PARTITION BY cp_department ORDER BY max_return DESC) AS rnk_max FROM reason_agg ) SELECT cp_id, cp_department, r_reason_desc, cd_gender, return_events, total_return_amount, avg_quantity, max_return, CASE WHEN rnk_max = 1 THEN 'Dept Max Return' ELSE 'Other' END AS max_return_category FROM ranked_reason WHERE return_events >= 10 ORDER BY max_return DESC, cp_id
